// Auto-generated from: vengabus.mid
// NOTE: Durations are absolute milliseconds from MIDI timing (tempo map honored).

// Octave transpose: -1

static const int8_t MOTOR_REST = -1;

struct MotorNoteEvent {
  int8_t note;
  int8_t octave;
  uint16_t duration_ms;
} __attribute__((packed));

static inline void playMotorEvent(const MotorNoteEvent &ev) {
  if (ev.note == MOTOR_REST) {
    longDelayMicroseconds((unsigned long)(ev.duration_ms * 1000UL));
    return;
  }
  playFreq(music_noteTable[(int)ev.note][(int)ev.octave], (float)ev.duration_ms / 1000.0f);
}

